al_0_y_0"],"layerType":"data","seriesType":"bar_horizontal","xAccessor":"bar_horizontal_0_x","yConfig":[{"axisMode":"left","forAccessor":"bar_horizontal_0_y_0"}]}]},"adHocDataViews":{"logs-*,metrics-*,*:logs-*,*:metrics-*-@timestamp-faae94b07bfcf6534a4191c9a664134bfba1b15054004380be49d33a1c62c7d9":{"id":"logs-*,metrics-*,*:logs-*,*:metrics-*-@timestamp-faae94b07bfcf6534a4191c9a664134bfba1b15054004380be49d33a1c62c7d9","title":"logs-*,metrics-*,*:logs-*,*:metrics-*","name":"logs-*,metrics-*,*:logs-*,*:metrics-*","timeFieldName":"@timestamp","sourceFilters":[],"allowNoIndex":false}},"query":{"language":"kuery","query":""},"filters":[]},"references":[]},"title":"Hosts / agents delivering","drilldowns":[]},"panelIndex":"40f2d8a2-a27c-4dfe-98b9-414c913b2349","gridData":{"y":0,"x":24,"w":24,"h":14,"i":"40f2d8a2-a27c-4dfe-98b9-414c913b2349","sectionId":"53b6cc09-439f-4f01-9a7a-f912dfb2f924"}},{"type":"custom_content","embeddableConfig":{"esql_query":["FROM traces-agent_builder.otel-default
| WHERE @timestamp >= NOW() - 30 days
    AND span.name LIKE "invoke_agent *"
    AND attributes.elastic.inference.span.kind == "CHAIN"
| STATS last_turn = MAX(@timestamp), first_turn = MIN(@timestamp), turn_count = COUNT(*), agent_name = VALUES(attributes.gen_ai.agent.name), user_hash = VALUES(user.hash) BY conversation_id = attributes.gen_ai.conversation.id, agent_id = attributes.gen_ai.agent.id
| SORT last_turn DESC
| LIMIT 200"],"template":"<style>
  body {
    margin: 0;
    padding: var(--cc-space-l);
    box-sizing: border-box;
    font-family: var(--cc-font-family);
    color: var(--cc-color-text);
    background: var(--cc-color-background);
  }

  .panel {
    background: var(--cc-color-surface);
    border: 1px solid var(--cc-color-border);
    border-radius: var(--cc-radius);
    padding: var(--cc-space-m);
    box-shadow: 0 1px 2px rgba(0,0,0,0.06);
  }

  details {
    border-radius: var(--cc-radius-s);
  }

  details.agent {
    border: 1px solid var(--cc-color-border);
    border-radius: var(--cc-radius);
    margin-bottom: var(--cc-space-s);
    overflow: hidden;
  }
  details.agent:last-child { margin-bottom: 0; }

  summary {
    list-style: none;
    cursor: pointer;
  }
  summary::-webkit-details-marker { display: none; }

  .agent-summary {
    display: flex;
    align-items: center;
    gap: var(--cc-space-s);
    padding: var(--cc-space-m);
    font-size: 0.875rem;
    font-weight: 600;
    transition: background var(--cc-motion-fast) var(--cc-ease);
  }
  .agent-summary:hover {
    background: var(--cc-color-background);
  }

  .agent-name {
    font-size: 1rem;
    font-weight: 600;
    flex: 1;
  }

  .agent-count {
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--cc-color-text);
    background: var(--cc-color-background);
    border: 1px solid var(--cc-color-border);
    padding: 2px var(--cc-space-s);
    border-radius: var(--cc-radius-s);
  }

  .chevron {
    flex-shrink: 0;
    transition: transform var(--cc-motion-fast) var(--cc-ease);
    color: var(--cc-color-text);
    opacity: 0.6;
  }
  details[open] > summary .chevron {
    transform: rotate(90deg);
  }

  .conversations {
    padding: 0 var(--cc-space-m) var(--cc-space-s) var(--cc-space-m);
    border-top: 1px solid var(--cc-color-border);
  }

  details.conversation {
    border-radius: var(--cc-radius-s);
    margin-top: var(--cc-space-s);
    background: var(--cc-color-background);
  }

  .conversation-summary {
    display: flex;
    align-items: center;
    gap: var(--cc-space-s);
    padding: var(--cc-space-s) var(--cc-space-m);
    font-size: 0.875rem;
    transition: background var(--cc-motion-fast) var(--cc-ease);
  }
  .conversation-summary:hover {
    background: var(--cc-color-surface);
  }

  .conv-title {
    flex: 1;
  }

  .turn-badge {
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--cc-color-primary);
    background: var(--cc-color-surface);
    border: 1px solid var(--cc-color-border);
    padding: 2px var(--cc-space-s);
    border-radius: var(--cc-radius-s);
  }

  .conversation-details {
    padding: 0 var(--cc-space-m) var(--cc-space-m) calc(var(--cc-space-m) + 20px);
    display: flex;
    flex-direction: column;
    gap: var(--cc-space-xs);
  }

  .detail-row {
    display: flex;
    justify-content: space-between;
    gap: var(--cc-space-m);
    font-size: 0.75rem;
  }

  .detail-row .label {
    color: var(--cc-color-text);
    opacity: 0.65;
  }

  .detail-row .value.mono {
    font-family: monospace;
  }

  .open-link {
    margin-top: var(--cc-space-s);
    display: inline-flex;
    align-items: center;
    gap: var(--cc-space-xs);
    align-self: flex-start;
    padding: var(--cc-space-xs) var(--cc-space-m);
    background: var(--cc-color-primary);
    color: var(--cc-color-surface);
    font-size: 0.75rem;
    font-weight: 600;
    border-radius: var(--cc-radius-s);
  }

  .open-url {
    margin-top: var(--cc-space-xs);
    font-size: 0.75rem;
    font-family: monospace;
    word-break: break-all;
    color: var(--cc-color-text);
    opacity: 0.7;
    background: var(--cc-color-surface);
    border: 1px solid var(--cc-color-border);
    border-radius: var(--cc-radius-s);
    padding: var(--cc-space-xs) var(--cc-space-s);
  }

  .empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--cc-space-s);
    padding: var(--cc-space-l);
    text-align: center;
  }
  .empty-state .icon {
    font-size: 1.5rem;
    opacity: 0.6;
  }
  .empty-state .title {
    font-size: 0.875rem;
    font-weight: 600;
  }
  .empty-state .subtitle {
    font-size: 0.75rem;
    opacity: 0.65;
    max-width: 32rem;
  }
</style>

<div class="panel">
  {% if rows.size == 0 %}
    <div class="empty-state">
      <div class="icon">💬</div>
      <div class="title">No conversations found</div>
      <div class="subtitle">There were no AI agent conversations in the selected time range. Try widening the time filter or check back after some activity occurs.</div>
    </div>
  {% else %}
    {% assign seen_agents = "" %}
    {% for row in rows %}
      {% assign agent_name = row["agent_name"].value %}
      {% assign marker = agent_name | append: "||" %}
      {% unless seen_agents contains marker %}
        {% assign seen_agents = seen_agents | append: marker %}
        {% assign agent_count = 0 %}
        {% for r in rows %}
          {% if r["agent_name"].value == agent_name %}
            {% assign agent_count = agent_count | plus: 1 %}
          {% endif %}
        {% endfor %}
        <details class="agent">
          <summary class="agent-summary">
            <svg class="chevron" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="9 6 15 12 9 18"></polyline>
            </svg>
            <span class="agent-name">{{ agent_name }}</span>
            <span class="agent-count">{{ agent_count }} conversation{% if agent_count != 1 %}s{% endif %}</span>
          </summary>
          <div class="conversations">
            {% for c in rows %}
              {% if c["agent_name"].value == agent_name %}
                <details class="conversation">
                  <summary class="conversation-summary">
                    <svg class="chevron" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                      <polyline points="9 6 15 12 9 18"></polyline>
                    </svg>
                    <span class="conv-title">Conversation – {{ c["last_turn"].value | date: "%b %d, %Y %H:%M" }}</span>
                    <span class="turn-badge">{{ c["turn_count"].value }} turns</span>
                  </summary>
                  <div class="conversation-details">
                    <div class="detail-row">
                      <span class="label">Conversation ID</span>
                      <span class="value mono">{{ c["conversation_id"].value }}</span>
                    </div>
                    <div class="detail-row">
                      <span class="label">First turn</span>
                      <span class="value">{{ c["first_turn"].value | date: "%b %d, %Y %H:%M:%S" }}</span>
                    </div>
                    <div class="detail-row">
                      <span class="label">Last turn</span>
                      <span class="value">{{ c["last_turn"].value | date: "%b %d, %Y %H:%M:%S" }}</span>
                    </div>
                    <div class="detail-row">
                      <span class="label">Turns</span>
                      <span class="value">{{ c["turn_count"].value }}</span>
                    </div>
                    <div class="open-link">Open conversation ↗</div>
                    <div class="open-url">https://gcp-observability-cockpit-f3b039.kb.europe-west3.gcp.elastic.cloud/app/agent_builder/conversations/{{ c["conversation_id"].value }}</div>
                  </div>
                </details>
              {% endif %}
            {% endfor %}
          </div>
        </details>
      {% endunless %}
    {% endfor %}
  {% endif %}
</div>"},"panelIndex":"fd973582-6bd1-4978-ad34-05ca18b4dafd","gridData":{"y":3,"x":0,"w":48,"h":13,"i":"fd973582-6bd1-4978-ad34-05ca18b4dafd","sectionId":"de8c14a3-b2e9-4e5a-8dac-f7f31f4d838d"}},{"type":"vis","panelIndex":"1dfcd0c5-db92-46ee-a0cc-6b38079265ab","gridData":{"x":0,"y":4,"w":12,"h":4,"i":"1dfcd0c5-db92-46ee-a0cc-6b38079265ab"},"embeddableConfig":{"title":"","enhancements":{},"attributes":{"title":"","visualizationType":"lnsMetric","version":2,"state":{"datasourceStates":{"textBased":{"layers":{"layer_0":{"index":"gcp-cockpit-security-kpi","query":{"esql":"FROM gcp-cockpit-security-kpi
