<head>
<style>
  body {
    margin: 0;
    padding: var(--cc-space-l);
    box-sizing: border-box;
    font-family: var(--cc-font-family);
    color: var(--cc-color-text);
    background: var(--cc-color-background);
  }

  .nav {
    display: flex;
    flex-direction: column;
    gap: var(--cc-space-m);
    width: 100%;
    box-sizing: border-box;
  }

  .hero {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--cc-space-l);
    padding: var(--cc-space-m) var(--cc-space-xl);
    border-radius: var(--cc-radius);
    background: linear-gradient(120deg, #07141f 0%, #0b3d42 40%, #0b5e6b 70%, #1a73e8 100%);
    box-shadow: 0 2px 12px rgba(0,0,0,0.18);
    color: #ffffff;
  }

  .hero-copy {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
  }

  .hero-kicker {
    font-size: 0.6875rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #48EFCF;
  }

  .hero-title {
    font-size: 1.125rem;
    font-weight: 600;
    line-height: 1.25;
    color: #ffffff;
  }

  .hero-sub {
    font-size: 0.8125rem;
    color: rgba(255,255,255,0.78);
    line-height: 1.35;
  }

  .chips {
    display: flex;
    flex-wrap: wrap;
    gap: var(--cc-space-s);
    justify-content: flex-end;
  }
  .chip-form { margin: 0; display: inline-flex; }

  .chip {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.4rem 0.75rem;
    border-radius: var(--cc-radius-s);
    background: rgba(255,255,255,0.10);
    border: 1px solid rgba(255,255,255,0.22);
    color: #ffffff;
    font-size: 0.75rem;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    transition: background var(--cc-motion-fast) var(--cc-ease),
                border-color var(--cc-motion-fast) var(--cc-ease),
                transform var(--cc-motion-fast) var(--cc-ease);
  }
  .chip:hover {
    background: rgba(255,255,255,0.18);
    border-color: rgba(255,255,255,0.4);
    transform: translateY(-1px);
  }
  .chip-dot {
    width: 0.45rem;
    height: 0.45rem;
    border-radius: 50%;
    background: #48EFCF;
    flex-shrink: 0;
  }
  .chip-alert .chip-dot { background: #FF957D; }
  .chip-warn .chip-dot { background: #FEC514; }
  .chip-info .chip-dot { background: #0B64DD; }
  .chip-ok .chip-dot { background: #48EFCF; }
  .chip-arrow { opacity: 0.7; }

  .groups {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: var(--cc-space-m);
  }

  .group {
    background: var(--cc-color-surface);
    border: 1px solid var(--cc-color-border);
    border-radius: var(--cc-radius);
    padding: var(--cc-space-m);
    box-shadow: 0 1px 2px rgba(0,0,0,0.04);
    min-width: 0;
  }

  .group-title {
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--cc-color-text);
    margin-bottom: var(--cc-space-s);
    padding-bottom: var(--cc-space-xs);
    border-bottom: 2px solid #48EFCF;
    border-bottom-width: 2px;
    width: fit-content;
  }

  .tiles {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
  }
  .tile-form { margin: 0; }

  .tile {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--cc-space-s);
    width: 100%;
    padding: 0.45rem 0.65rem;
    border-radius: var(--cc-radius-s);
    border: 1px solid transparent;
    color: var(--cc-color-text);
    background: transparent;
    font-size: 0.8125rem;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    text-align: left;
    transition: background var(--cc-motion-fast) var(--cc-ease),
                border-color var(--cc-motion-fast) var(--cc-ease),
                transform var(--cc-motion-fast) var(--cc-ease);
  }
  .tile:hover {
