<div class="wrap">
  <div class="hero">
    <div>
      <div class="kicker">Insight fabric</div>
      <div class="title">GCP posture at a glance</div>
      <div class="sub">Security KPIs mirrored from the Security project · coverage & recommendations computed by workflows · click any tile to drill down</div>
    </div>
  </div>
  <div class="grid">
    {% assign row = rows[0] %}
    <form class="card sev-high" action="/app/security/alerts" method="get" target="_top">
      <button type="submit" class="card-btn">
        <div class="label">Active alerts</div>
        <div class="value">{{ row["active_alerts"].value | default: 0 }}</div>
        <div class="hint">Open Security alerts →</div>
      </button>
    </form>
    <form class="card sev-high" action="/app/security/alerts" method="get" target="_top">
      <button type="submit" class="card-btn">
        <div class="label">High / critical</div>
        <div class="value">{{ row["high_critical_alerts"].value | default: 0 }}</div>
        <div class="hint">Prioritize these first →</div>
      </button>
    </form>
    <form class="card " action="/app/dashboards#/view/gcp-48e12760-cbe4-11ec-b519-85ccf621cbbf" method="get" target="_top">
      <button type="submit" class="card-btn">
        <div class="label">Audit (24h)</div>
        <div class="value">{{ row["audit_24h"].value | default: row["activity_24h"].value | default: row["cloudtrail_24h"].value | default: 0 }}</div>
        <div class="hint">Open Audit dashboard →</div>
      </button>
    </form>
    <form class="card sev-ok" action="/app/security/cloud_security_posture/findings/misconfigurations" method="get" target="_top">
      <button type="submit" class="card-btn">
        <div class="label">CSPM findings</div>
        <div class="value">{{ row["cspm_findings"].value | default: 0 }}</div>
        <div class="hint">Open CSPM findings →</div>
      </button>
    </form>
  </div>
</div>
</body>
</html>
